import React, { useEffect } from 'react';
import MonacoEditor from '@monaco-editor/react';

/**
 * EditorComponent - Code editor using Monaco Editor
 * Provides syntax highlighting and code editing capabilities
 */
const EditorComponent = ({ code, onCodeChange, isDarkMode }) => {
  
  // Define custom language for EVENTRA
  useEffect(() => {
    if (window.monaco) {
      // Register custom language
      window.monaco.languages.register({ id: 'eventra' });
      
      // Define syntax highlighting rules
      window.monaco.languages.setMonarchTokensProvider('eventra', {
        tokenizer: {
          root: [
            // Keywords
            [/\b(start|on|say|input)\b/, 'keyword'],
            
            // Strings
            [/"[^"]*"/, 'string'],
            
            // Comments
            [/#.*$/, 'comment'],
            
            // Braces
            [/[{}]/, 'delimiter.bracket'],
            
            // Numbers
            [/\d+/, 'number'],
            
            // Identifiers (variable names)
            [/[a-zA-Z_][a-zA-Z0-9_]*/, 'identifier'],
          ]
        }
      });
      
      // Set custom colors for the language
      window.monaco.editor.defineTheme('eventra-dark', {
        base: 'vs-dark',
        inherit: true,
        rules: [
          { token: 'keyword', foreground: 'C586C0', fontStyle: 'bold' },
          { token: 'string', foreground: 'CE9178' },
          { token: 'comment', foreground: '6A9955', fontStyle: 'italic' },
          { token: 'number', foreground: 'B5CEA8' },
          { token: 'identifier', foreground: '9CDCFE' },
          { token: 'delimiter', foreground: 'D4D4D4' },
        ],
        colors: {}
      });
      
      window.monaco.editor.defineTheme('eventra-light', {
        base: 'light',
        inherit: true,
        rules: [
          { token: 'keyword', foreground: 'AF00DB', fontStyle: 'bold' },
          { token: 'string', foreground: 'A31515' },
          { token: 'comment', foreground: '008000', fontStyle: 'italic' },
          { token: 'number', foreground: '098658' },
          { token: 'identifier', foreground: '001080' },
          { token: 'delimiter', foreground: '000000' },
        ],
        colors: {}
      });
      
      // Register auto-completion provider
      window.monaco.languages.registerCompletionItemProvider('eventra', {
        provideCompletionItems: (model, position) => {
          const word = model.getWordUntilPosition(position);
          const range = {
            startLineNumber: position.lineNumber,
            endLineNumber: position.lineNumber,
            startColumn: word.startColumn,
            endColumn: word.endColumn
          };
          
          return {
            suggestions: [
              {
                label: 'start',
                kind: window.monaco.languages.CompletionItemKind.Keyword,
                insertText: 'start {\n    $0\n}',
                insertTextRules: window.monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet,
                documentation: 'Entry point event (auto-executes)',
                range: range
              },
              {
                label: 'on',
                kind: window.monaco.languages.CompletionItemKind.Keyword,
                insertText: 'on ${1:eventName} {\n    $0\n}',
                insertTextRules: window.monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet,
                documentation: 'Define an event handler',
                range: range
              },
              {
                label: 'say',
                kind: window.monaco.languages.CompletionItemKind.Keyword,
                insertText: 'say $0',
                insertTextRules: window.monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet,
                documentation: 'Print output',
                range: range
              },
              {
                label: 'input',
                kind: window.monaco.languages.CompletionItemKind.Keyword,
                insertText: 'input ${1:variableName}',
                insertTextRules: window.monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet,
                documentation: 'Get user input',
                range: range
              }
            ]
          };
        }
      });
    }
  }, []);
  
  // Monaco Editor configuration
  const editorOptions = {
    minimap: { enabled: false },
    fontSize: 14,
    lineNumbers: 'on',
    scrollBeyondLastLine: false,
    automaticLayout: true,
    padding: { top: 10, bottom: 10 },
    wordWrap: 'on',
    renderWhitespace: 'selection',
    quickSuggestions: true,  // Enable auto-suggestions
    suggestOnTriggerCharacters: true,
    acceptSuggestionOnEnter: 'smart',
  };
  
  // Monaco theme configuration
  const theme = isDarkMode ? currentTheme : 'eventra-light';
  
  return (
    <div className="editor-container" style={{ 
      flex: 1, 
      minHeight: '400px',
      border: '2px solid var(--border-color)',
      borderRadius: '8px',
      overflow: 'hidden'
    }}>
      <MonacoEditor
        height="100%"
        language="eventra"
        theme={theme}
        value={code}
        onChange={(value) => onCodeChange(value || '')}
        options={editorOptions}
      />
    </div>
  );
};

export default EditorComponent;
